  1	import java.util.Objects;
  2	import java.util.StringJoiner;
  3	
  4	final class BuildHeap {
  5	    private static final String VALUE_SEPARATOR = " ";
  6	    private static final int[] SAMPLE_VALUES = {1, 3, 5, 4, 6, 13, 10, 9, 8, 15, 17};
  7	
  8	    private BuildHeap() {
  9	    }
 10	
 11	    static void buildHeap(int[] values) {
 12	        buildMaxHeap(values);
 13	    }
 14	
 15	    static void buildMaxHeap(int[] values) {
 16	        Objects.requireNonNull(values, "values");
 17	
 18	        for (int index = lastParentIndex(values.length); index >= 0; index--) {
 19	            siftDown(values, values.length, index);
 20	        }
 21	    }
 22	
 23	    private static void siftDown(int[] values, int heapSize, int startIndex) {
 24	        int currentIndex = startIndex;
 25	
 26	        while (hasLeftChild(currentIndex, heapSize)) {
 27	            int largerChildIndex = largerChildIndex(values, heapSize, currentIndex);
 28	
 29	            if (isHeapOrdered(values, currentIndex, largerChildIndex)) {
 30	                return;
 31	            }
 32	
 33	            swap(values, currentIndex, largerChildIndex);
 34	            currentIndex = largerChildIndex;
 35	        }
 36	    }
 37	
 38	    private static boolean hasLeftChild(int index, int heapSize) {
 39	        return leftChildIndex(index) < heapSize;
 40	    }
 41	
 42	    private static int largerChildIndex(int[] values, int heapSize, int parentIndex) {
 43	        int leftChildIndex = leftChildIndex(parentIndex);
 44	        int rightChildIndex = rightChildIndex(parentIndex);
 45	
 46	        if (isRightChildLarger(values, heapSize, leftChildIndex, rightChildIndex)) {
 47	            return rightChildIndex;
 48	        }
 49	
 50	        return leftChildIndex;
 51	    }
 52	
 53	    private static boolean isHeapOrdered(int[] values, int parentIndex, int childIndex) {
 54	        return values[parentIndex] >= values[childIndex];
 55	    }
 56	
 57	    private static boolean isRightChildLarger(
 58	            int[] values,
 59	            int heapSize,
 60	            int leftChildIndex,
 61	            int rightChildIndex) {
 62	        return rightChildIndex < heapSize && values[rightChildIndex] > values[leftChildIndex];
 63	    }
 64	
 65	    private static int leftChildIndex(int index) {
 66	        return 2 * index + 1;
 67	    }
 68	
 69	    private static int rightChildIndex(int index) {
 70	        return 2 * index + 2;
 71	    }
 72	
 73	    private static void swap(int[] values, int firstIndex, int secondIndex) {
 74	        int temp = values[firstIndex];
 75	        values[firstIndex] = values[secondIndex];
 76	        values[secondIndex] = temp;
 77	    }
 78	
 79	    private static int lastParentIndex(int heapSize) {
 80	        return heapSize / 2 - 1;
 81	    }
 82	
 83	    private static String formatValues(int[] values) {
 84	        if (values.length == 0) {
 85	            return "";
 86	        }
 87	
 88	        StringJoiner output = new StringJoiner(VALUE_SEPARATOR);
 89	
 90	        for (int value : values) {
 91	            output.add(Integer.toString(value));
 92	        }
 93	
 94	        return output.toString() + VALUE_SEPARATOR;
 95	    }
 96	
 97	    private static int[] sampleValues() {
 98	        return SAMPLE_VALUES.clone();
 99	    }
100	
101	    public static void main(String[] args) {
102	        int[] values = sampleValues();
103	
104	        buildMaxHeap(values);
105	        System.out.println(formatValues(values));
106	    }
107	}
